#!/usr/bin/env node
"use strict";
/*
 * V17.5 — NATIVE BUILD RUNNER (contract docs/odg/evidence/V175_NATIVE_BUILD_CONTRACT.json, scenario V175-NB1). This file
 * is the contract's DECLARED dispatch target authorization.dispatchTargets.RUN_NATIVE_BUILD: ODG GO runs
 *   npx tsx runtime/bin/odg-v175-native-build-run.ts docs/odg/evidence/V175_NATIVE_BUILD_RESULT.json
 * in its isolated scratch. Provider (Claude Code) wrote this RUNNER (plumbing). The PATCH CONTENT is generated by ODG's
 * LOCAL model (Ollama 127.0.0.1:11434); this runner never edits generated code — it only transpiles it (TypeScript →
 * JavaScript, a build step) to execute it in the sandbox, and records every generation's sha256 + source.
 *
 * LOOP (composes canonical components; no 2nd engine): DETECT (odg-native-repair-item.detectCanonDefects — re-run, must
 * reproduce the contract's evidence digest) → SPEC (contract moduleSpec + computed oracle) → GENERATE (local model) →
 * TEST (native-project-builder.buildProject, SANDBOX mode = odg-native-build-sandbox.runIsolated in bwrap, held-out
 * oracle graded host-side) → ANALYSE + REPAIR (buildProject's bounded repair with the specific first failing repair
 * example) → VERIFY (strict in-memory typecheck; a type failure starts ONE more bounded round with the diagnostics as
 * the hint) → PRODUCE (branch-ready diff + git apply --check, NOTHING written into any checkout) → PROVENANCE record.
 *
 * MODES:
 *   <out>                 NATIVE run (GO dispatch). Refused (exit 2) unless the contract is AUTHORIZED with authorizedBy;
 *                         <out> must equal the declared writeSet entry (exit 3). Exactly one write: <out>.
 *   --probe --out <abs>   feasibility PROBE (label PROBE, never the native result); <abs> must be OUTSIDE the repo.
 *   --emit-contract       print the contract ODG's rules derive from the CURRENT repo (stdout only).
 *   --selftest            offline: fake-Ollama transport behind the real loopback guard; real sandbox; nothing written.
 * NETWORK: guardedFetch — exact http://127.0.0.1:11434 allowlist over scenario F's node:http loopbackFetch; anything
 *   else is refused and recorded (⇒ NOT_MEASURED). 0 provider calls.
 */
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const cp = require("child_process");
const NRI = require("../core/odg-native-repair-item.js");
const BUILDER = require("../core/native-project-builder.js");
const NBS = require("../core/odg-native-build-sandbox.js");
const GEN = require("../core/local-model-generator.js");
const NE = require("../core/odg-native-engineering.js");

const ROOT = path.resolve(__dirname, "..", "..");
const SELF = "runtime/bin/odg-v175-native-build-run.ts";
const CONTRACT = "docs/odg/evidence/V175_NATIVE_BUILD_CONTRACT.json";
const OUT = "docs/odg/evidence/V175_NATIVE_BUILD_RESULT.json";
const OLLAMA = Object.freeze({ protocol: "http:", host: "127.0.0.1", port: "11434" });
const BUDGETS = Object.freeze({ model: "qwen2.5-coder:7b", temperature: 0, seed: 42, numPredict: 900, maxRepairPerRound: 3, maxRounds: 2, maxModelCalls: 10, wallMs: 1500000, perCallTimeoutMs: 300000 });
const sha256 = (s: any): string => crypto.createHash("sha256").update(String(s)).digest("hex");

/* ---------------- network guard ---------------- */
function makeGuard(transport: any, caps: any = BUDGETS): any {
  const st: any = { modelCalls: 0, refused: [] as any[], prompts: [] as any[], capHit: null as any, deadline: Date.now() + caps.wallMs };
  const fetchImpl = async (url: any, init: any = {}): Promise<any> => {
    let u: any = null; try { u = new URL(String(url)); } catch { /* refused */ }
    if (!u || u.protocol !== OLLAMA.protocol || u.hostname !== OLLAMA.host || u.port !== OLLAMA.port || u.pathname !== "/api/generate") {
      st.refused.push(String(url).slice(0, 200));
      throw new Error("V175 network guard: only http://127.0.0.1:11434/api/generate is allowed");
    }
    if (st.modelCalls >= caps.maxModelCalls) { st.capHit = st.capHit || "maxModelCalls"; throw new Error("V175 cap: maxModelCalls"); }
    if (Date.now() > st.deadline) { st.capHit = st.capHit || "wallMs"; throw new Error("V175 cap: wallMs"); }
    const body = init && typeof init.body === "string" ? JSON.parse(init.body) : {};
    body.options = { ...(body.options || {}), seed: caps.seed, temperature: caps.temperature, num_predict: caps.numPredict };
    st.modelCalls++;
    st.prompts.push({ i: st.modelCalls, model: body.model, promptSha256: sha256(body.prompt || ""), promptChars: String(body.prompt || "").length });
    return transport(String(url), { ...init, body: JSON.stringify(body) });
  };
  return { st, fetchImpl };
}

/* ---------------- TypeScript build steps (no semantic change) ---------------- */
function transpile(tsSrc: string): any {
  const ts = require("typescript");
  const r = ts.transpileModule(tsSrc, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 }, reportDiagnostics: true });
  const diags = (r.diagnostics || []).map((d: any) => ts.flattenDiagnosticMessageText(d.messageText, "\n"));
  return { js: r.outputText, syntaxErrors: diags };
}
/* typecheck(tsSrc) — strict + isolatedModules in-memory program; CommonJS globals declared `any` (no @types needed). */
function typecheck(tsSrc: string): any {
  const ts = require("typescript");
  const F = "/odg-v175/odg-canonical-json.ts", A = "/odg-v175/ambient.d.ts";
  const mem: any = { [F]: tsSrc, [A]: "declare var module: any;\ndeclare var require: any;\ndeclare var exports: any;\n" };
  const options = { strict: true, noEmit: true, isolatedModules: true, target: ts.ScriptTarget.ES2020, lib: ["lib.es2020.d.ts"], types: [], skipLibCheck: true };
  const host = ts.createCompilerHost(options);
  const gsf = host.getSourceFile.bind(host);
  host.getSourceFile = (n: string, lv: any, ...rest: any[]) => mem[n] !== undefined ? ts.createSourceFile(n, mem[n], lv) : gsf(n, lv, ...rest);
  const fe = host.fileExists.bind(host); host.fileExists = (n: string) => mem[n] !== undefined || fe(n);
  const rf = host.readFile.bind(host); host.readFile = (n: string) => mem[n] !== undefined ? mem[n] : rf(n);
  const prog = ts.createProgram([F, A], options, host);
  const diags = ts.getPreEmitDiagnostics(prog).map((d: any) => (d.file ? path.basename(d.file.fileName) + (d.start !== undefined ? ":" + (d.file.getLineAndCharacterOfPosition(d.start).line + 1) : "") + " " : "") + ts.flattenDiagnosticMessageText(d.messageText, " "));
  return { ok: diags.length === 0, diagnostics: diags.slice(0, 10) };
}

/* ---------------- the local-model seam (prompt for a TS module; same Ollama call shape as local-model-generator) ---- */
function buildPrompt(fileSpec: any): string {
  const lines = [
    "You are writing exactly ONE TypeScript source file for a strict TypeScript repository that uses CommonJS.",
    "Output ONLY the TypeScript source. No explanation, no markdown fences, no prose.",
    "Requirements: no import statements; annotate every parameter and return type (use `any` for the value);",
    "export with module.exports = { ... }; and put `export {};` as the LAST line of the file.",
    "",
    `File: ${NRI.TARGET_MODULE}`,
    "Contract (must be satisfied exactly):",
    String(fileSpec.contract || ""),
  ];
  if (fileSpec.buildError) lines.push("", "A previous attempt FAILED to build with this error — fix it:", "  " + String(fileSpec.buildError));
  if (fileSpec.verifyError) lines.push("", "A previous attempt BUILT but FAILED the functional test — fix the LOGIC:", "  " + String(fileSpec.verifyError));
  if (fileSpec.typeError) lines.push("", "A previous attempt PASSED the tests but FAILED the strict TypeScript typecheck — fix the types:", "  " + String(fileSpec.typeError));
  lines.push("", "Now output only the code:");
  return lines.join("\n");
}
function makeGenerator(fetchImpl: any, log: any[], round: number, extraHint: any): any {
  return async function generateFile(fileSpec: any): Promise<any> {
    const spec = { ...fileSpec, ...(extraHint && !fileSpec.buildError && !fileSpec.verifyError ? extraHint : {}) };
    const prompt = buildPrompt(spec);
    const t0 = Date.now();
    const rec: any = { round, i: log.length + 1, model: BUDGETS.model, promptSha256: sha256(prompt), hint: spec.buildError ? "buildError" : spec.verifyError ? "verifyError" : spec.typeError ? "typeError" : null };
    log.push(rec);
    try {
      const ctl = new AbortController(); const timer = setTimeout(() => ctl.abort(), BUDGETS.perCallTimeoutMs);
      let res: any; try { res = await fetchImpl(`http://${OLLAMA.host}:${OLLAMA.port}/api/generate`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ model: BUDGETS.model, prompt, stream: false }), signal: ctl.signal }); } finally { clearTimeout(timer); }
      rec.ms = Date.now() - t0;
      if (!res || res.ok !== true) { rec.ok = false; rec.reason = `HTTP ${res && res.status}`; return { ok: false }; }
      const j = await res.json();
      rec.evalCount = (j && j.eval_count) || null; rec.respondedModel = (j && j.model) || null;
      const tsSrc = GEN.extractCode(j && j.response);       // canonical fence-stripping + module check (fail-closed)
      if (!tsSrc) { rec.ok = false; rec.reason = "no CommonJS module extracted"; rec.raw = String((j && j.response) || "").slice(0, 2000); return { ok: false }; }
      const t = transpile(tsSrc);
      rec.ok = true; rec.tsSource = tsSrc; rec.tsSha256 = sha256(tsSrc); rec.syntaxErrors = t.syntaxErrors;
      // syntax errors ⇒ hand the RAW source to the sandbox so the build fails with the real parser message (repair hint)
      const content = t.syntaxErrors.length ? tsSrc : t.js;
      rec.sandboxContentSha256 = sha256(content);
      return { ok: true, content };
    } catch (e: any) { rec.ms = Date.now() - t0; rec.ok = false; rec.reason = String((e && e.message) || e).slice(0, 300); return { ok: false }; }
  };
}

/* ---------------- branch-ready diff ---------------- */
function newFileDiff(rel: string, content: string): string {
  const body = content.endsWith("\n") ? content : content + "\n";
  const ls = body.slice(0, -1).split("\n");
  return [`diff --git a/${rel} b/${rel}`, "new file mode 100644", "--- /dev/null", `+++ b/${rel}`, `@@ -0,0 +1,${ls.length} @@`, ...ls.map((l) => "+" + l)].join("\n") + "\n" + (content.endsWith("\n") ? "" : "\\ No newline at end of file\n");
}
/* oracle test file — authored by ODG RULES from the computed oracle (deterministic; not model, not hand-written) */
function oracleTestSource(oracle: any): string {
  const all = oracle.repairExamples.map((r: any) => ({ args: r.args, expect: r.expect })).concat(oracle.acceptanceCases.map((c: any) => ({ args: c.args, expect: c.expect })));
  return [
    "#!/usr/bin/env node",
    "\"use strict\";",
    `/* GENERATED by ODG rules (runtime/core/odg-native-repair-item.ts ORC-1/REF-1) — oracle sha256 ${oracle.sha256}; expected values computed`,
    ` * by executing the in-repo reference canon() (sha256 ${oracle.referenceSha256}). Not model-authored, not hand-written. */`,
    `const M = require("./odg-canonical-json.js");`,
    `const CASES: any[] = ${JSON.stringify(all)};`,
    "let failures = 0;",
    `CASES.forEach((c: any, i: number) => { const got = M.${NRI.EXPORT_NAME}(c.args[0]); const ok = got === c.expect; process.stdout.write((ok ? "ok" : "NOT OK") + " - case " + i + " " + JSON.stringify(c.args[0]) + "\\n"); if (!ok) failures++; });`,
    "if (failures) { process.stdout.write(failures + \" failure(s)\\n\"); process.exit(1); }",
    "export {};",
    "",
  ].join("\n");
}
function gitApplyCheck(root: string, diff: string): any {
  const r = cp.spawnSync("git", ["-C", root, "apply", "--check", "-"], { input: diff, encoding: "utf8", timeout: 30000 });
  return { ok: r.status === 0, stderr: String(r.stderr || "").slice(0, 500) };
}
function headOf(root: string): string | null { try { return String(cp.execFileSync("git", ["-C", root, "rev-parse", "HEAD"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] })).trim(); } catch { return null; } }

/* ---------------- the native build ---------------- */
async function runNativeBuild(opts: any): Promise<any> {
  const root = opts.root || ROOT;
  const t0 = Date.now();
  const detection = NRI.detectCanonDefects(root);
  const oracle = NRI.buildOracle(detection);
  const base: any = { schema: "odg-native-build-result/1", label: opts.label, scenario: "V175-NB1", run: { head: headOf(root), startedAt: new Date(t0).toISOString(), runner: SELF }, budgets: BUDGETS,
    detection: { defect: detection.defect, defectClass: detection.defectClass, evidenceDigest: detection.evidenceDigest, defectiveSites: detection.defectiveSites, reference: detection.reference, scanned: detection.scanned, targetExists: detection.targetExists } };
  const finish = (x: any) => ({ ...base, ...x, wallMs: Date.now() - t0 });
  if (!detection.defect || !oracle) return finish({ verdict: "NOT_MEASURED", reason: detection.targetExists ? "target module already exists — nothing to build" : "no defect detected / no reference (nothing to repair)" });
  if (opts.expectedDigest && opts.expectedDigest !== detection.evidenceDigest) return finish({ verdict: "NOT_MEASURED", reason: `AC5 detection drift: fresh evidenceDigest ${detection.evidenceDigest} ≠ contract ${opts.expectedDigest}` });
  if (opts.expectedOracleSha && opts.expectedOracleSha !== oracle.sha256) return finish({ verdict: "NOT_MEASURED", reason: `oracle drift: ${oracle.sha256} ≠ contract ${opts.expectedOracleSha}` });

  const guard = makeGuard(opts.transport);
  const generations: any[] = [];
  const rounds: any[] = [];
  const spec: any = {
    name: "V175-NB1 odg-canonical-json",
    architecture: [{ path: NRI.SANDBOX_FILE, role: "shared canonical-JSON serializer", contract: NRI.MODULE_SPEC, dependsOn: [] }],
    writeSet: [NRI.SANDBOX_FILE], entry: NRI.SANDBOX_FILE,
    independentTestCases: oracle.acceptanceCases,
    repairExamples: oracle.repairExamples.map((r: any) => ({ args: r.args, expect: r.expect })),
  };
  let accepted: any = null; let extraHint: any = null;
  for (let round = 1; round <= BUDGETS.maxRounds && !accepted; round++) {
    const out = await BUILDER.buildProject(spec, { generateFile: makeGenerator(guard.fetchImpl, generations, round, extraHint), maxRepair: BUDGETS.maxRepairPerRound, sandboxRunner: opts.sandboxRunner });
    const finalJs = out.files ? out.files[NRI.SANDBOX_FILE] : null;
    const gen = [...generations].reverse().find((g: any) => g.round === round && g.ok && g.sandboxContentSha256 === (finalJs ? sha256(finalJs) : null));
    const r: any = { round, buildOk: out.buildOk, verified: out.verified, accepted: out.accepted, repairs: out.repairs, repairStopReason: out.repairStopReason, verifyError: out.verifyError, buildError: out.buildError, executionMode: out.executionMode, executionStatus: out.executionStatus, isolation: out.isolation, firstPass: out.firstPass, finalTsSha256: gen ? gen.tsSha256 : null };
    rounds.push(r);
    if (out.executionStatus !== "EXECUTED" || out.executionMode !== "SANDBOX") { r.typecheck = null; break; }
    if (out.accepted && gen) {
      r.typecheck = typecheck(gen.tsSource);
      if (r.typecheck.ok) accepted = gen; else extraHint = { typeError: r.typecheck.diagnostics.join(" | ") };
    }
    if (guard.st.capHit) break;
  }
  const network = { modelCalls: guard.st.modelCalls, prompts: guard.st.prompts, refused: guard.st.refused, capHit: guard.st.capHit, providerCalls: 0 };
  const notMeasured = guard.st.refused.length > 0 || rounds.some((r: any) => r.executionStatus !== "EXECUTED" || r.executionMode !== "SANDBOX");
  const provenance = { actor: "ODG", executionClass: NE.EXEC.LOCAL, patchAuthoredBy: `local model ${BUDGETS.model} via Ollama 127.0.0.1:11434`, testAuthoredBy: "ODG_RULES (oracleTestSource from ORC-1/REF-1)", runnerAuthoredBy: "PROVIDER (Claude Code) — plumbing only", providerEditedGeneratedCode: false, providerCalls: 0 };
  if (notMeasured) return finish({ verdict: "NOT_MEASURED", reason: guard.st.refused.length ? "non-loopback request refused" : "sandbox did not execute (NOT_RUN) — no verdict", rounds, generations, network, provenance });
  if (!accepted) return finish({ verdict: "FAIL", reason: `no generation passed AC1+AC2 within ${BUDGETS.maxRounds} rounds × (1 + ${BUDGETS.maxRepairPerRound} repairs)${guard.st.capHit ? " (cap " + guard.st.capHit + ")" : ""}`, rounds, generations, network, provenance });
  const testSrc = oracleTestSource(oracle);
  const diff = newFileDiff(NRI.TARGET_MODULE, accepted.tsSource) + newFileDiff(NRI.TARGET_TEST, testSrc);
  const applyCheck = gitApplyCheck(root, diff);
  const patch = { files: [{ path: NRI.TARGET_MODULE, sha256: sha256(accepted.tsSource), authoredBy: "LOCAL_MODEL", generation: accepted.i }, { path: NRI.TARGET_TEST, sha256: sha256(testSrc), authoredBy: "ODG_RULES" }], diff, diffSha256: sha256(diff), gitApplyCheck: applyCheck };
  return finish({ verdict: applyCheck.ok ? "PASS" : "FAIL", reason: applyCheck.ok ? "AC1 held-out oracle PASS in sandbox + AC2 strict typecheck PASS + AC3 git apply --check OK" : "AC3 failed: diff does not apply", rounds, generations, network, provenance, patch,
    integration: "OWNER_GATED: apply patch.diff on a branch and open a PR (no checkout is written by this runner); migrating audit-log / agent-identity / supply-chain-attest to the helper changes persisted hash/signature preimages ⇒ separate owner decision" });
}

/* ---------------- CLI ---------------- */
function readContract(root: string): any { try { return JSON.parse(fs.readFileSync(path.join(root, CONTRACT), "utf8")); } catch { return null; } }
function contractFor(root: string): any {
  const d = NRI.detectCanonDefects(root);
  return NRI.buildContract(d, NRI.buildOracle(d), { command: SELF, out: OUT, budgets: BUDGETS });
}
function loopbackTransport(): any { return require("./odg-v161-scenario-f-run.js").loopbackFetch; }

async function selftest(): Promise<number> {
  let f = 0; const check = (n: string, c: boolean) => { process.stdout.write((c ? "ok" : "NOT OK") + " - " + n + "\n"); if (!c) f++; };
  // FAKE OLLAMA (test fixture, NOT a native result): 1st answer has a logic bug (nested keys unsorted), 2nd is correct.
  const WRONG = "function canonicalJson(value: any): string {\n  if (Array.isArray(value)) return '[' + value.map(canonicalJson).join(',') + ']';\n  if (value !== null && typeof value === 'object') return JSON.stringify(value);\n  return JSON.stringify(value);\n}\nmodule.exports = { canonicalJson };\nexport {};\n";
  const RIGHT = "function canonicalJson(value: any): string {\n  if (Array.isArray(value)) return '[' + value.map(canonicalJson).join(',') + ']';\n  if (value !== null && typeof value === 'object') return '{' + Object.keys(value).sort().map((k: string) => JSON.stringify(k) + ':' + canonicalJson(value[k])).join(',') + '}';\n  return JSON.stringify(value);\n}\nmodule.exports = { canonicalJson };\nexport {};\n";
  let n = 0; const seen: string[] = [];
  const fake = async (url: string, init: any) => { n++; seen.push(url); const b = JSON.parse(init.body); return { ok: true, json: async () => ({ model: b.model, eval_count: 1, response: "```ts\n" + (n === 1 ? WRONG : RIGHT) + "```" }) }; };
  const probe = NBS.probeSandbox();
  const r = await runNativeBuild({ root: ROOT, label: "SELFTEST", transport: fake });
  check("detection: real defect found in this repo (NESTED_KEY_DROP in audit-log + agent-identity)", r.detection.defect === true && r.detection.defectiveSites.some((s: any) => s.file === "runtime/core/audit-log.ts" && s.verdict === "NESTED_KEY_DROP") && r.detection.defectiveSites.some((s: any) => s.file === "runtime/core/agent-identity.ts"));
  if (probe && probe.ok === true) {
    check("fake model: wrong first ⇒ repaired ⇒ PASS", r.verdict === "PASS" && r.rounds[0].repairs >= 1 && r.rounds[0].firstPass.verified === false);
    check("typecheck AC2 ran and passed", r.rounds[0].typecheck && r.rounds[0].typecheck.ok === true);
    check("diff adds exactly the 2 write-set files and applies", r.patch && /b\/runtime\/core\/odg-canonical-json\.ts/.test(r.patch.diff) && /b\/runtime\/core\/odg-canonical-json\.test\.ts/.test(r.patch.diff) && r.patch.gitApplyCheck.ok === true);
    check("provenance: actor ODG, local-model class, 0 provider calls, 2 model calls, prompt shas", r.provenance.actor === "ODG" && r.provenance.executionClass === "ODG_LOCAL_MODEL_EXECUTION" && r.network.providerCalls === 0 && r.network.modelCalls === 2 && r.network.prompts.every((p: any) => /^[0-9a-f]{64}$/.test(p.promptSha256)));
    check("only the loopback URL was requested", seen.every((u) => u === "http://127.0.0.1:11434/api/generate"));
  } else process.stdout.write("SKIP - sandbox unavailable (" + String(probe && probe.reason) + "): verdict must be NOT_MEASURED\n"), check("no sandbox ⇒ NOT_MEASURED", r.verdict === "NOT_MEASURED");
  const g = makeGuard(fake);
  let refused = false; try { await g.fetchImpl("http://10.0.0.1:11434/api/generate", { body: "{}" }); } catch { refused = true; }
  check("guard refuses a non-loopback URL and records it", refused && g.st.refused.length === 1);
  const tc = typecheck("function f(x) { return x; }\nmodule.exports = { f };\nexport {};\n");
  check("typecheck rejects implicit any (strict)", tc.ok === false);
  const drift = await runNativeBuild({ root: ROOT, label: "SELFTEST", transport: fake, expectedDigest: "0".repeat(64) });
  check("detection drift ⇒ NOT_MEASURED before any model call", drift.verdict === "NOT_MEASURED" && /drift/.test(drift.reason));
  return f;
}

async function main(argv: string[]): Promise<number> {
  if (argv[0] === "--selftest") return (await selftest()) === 0 ? 0 : 1;
  if (argv[0] === "--emit-contract") { process.stdout.write(JSON.stringify(contractFor(ROOT), null, 2) + "\n"); return 0; }
  if (argv[0] === "--probe") {
    const i = argv.indexOf("--out"); const out = i >= 0 ? argv[i + 1] : null;
    const ri = argv.indexOf("--repo"); const root = ri >= 0 ? path.resolve(argv[ri + 1]) : ROOT;
    if (!out || !path.isAbsolute(out) || path.resolve(out).startsWith(root + path.sep)) { process.stdout.write("REFUSED: --probe needs --out <absolute path outside the repo>\n"); return 3; }
    const r = await runNativeBuild({ root, label: "PROBE (provider-run feasibility probe — NOT the ODG-native GO result)", transport: loopbackTransport() });
    fs.writeFileSync(out, JSON.stringify(r, null, 2) + "\n");
    process.stdout.write(`PROBE verdict ${r.verdict} modelCalls ${r.network ? r.network.modelCalls : 0} wallMs ${r.wallMs} → ${out}\n`);
    return 0;
  }
  const out = argv[0];
  if (out !== OUT) { process.stdout.write(`REFUSED: output path must be the declared writeSet entry ${OUT}\n`); return 3; }
  const c = readContract(ROOT);
  if (!c || c.state !== "AUTHORIZED" || typeof c.authorizedBy !== "string" || !c.authorizedBy.trim()) { process.stdout.write(`NOT_AUTHORIZED: ${CONTRACT} is ${c ? c.state : "absent"} (needs AUTHORIZED + authorizedBy)\n`); return 2; }
  const r = await runNativeBuild({ root: ROOT, label: "NATIVE (ODG GO dispatch)", transport: loopbackTransport(), expectedDigest: c.origin && c.origin.evidenceDigest, expectedOracleSha: c.origin && c.origin.oracleSha256 });
  fs.writeFileSync(path.join(ROOT, OUT), JSON.stringify(r, null, 2) + "\n");
  process.stdout.write(`NATIVE verdict ${r.verdict} → ${OUT}\n`);
  return r.verdict === "PASS" ? 0 : 1;
}

module.exports = { runNativeBuild, makeGuard, typecheck, transpile, buildPrompt, newFileDiff, oracleTestSource, contractFor, BUDGETS, SELF, OUT, CONTRACT };
if (require.main === module) main(process.argv.slice(2)).then((c) => process.exit(c), (e) => { process.stdout.write("ERROR " + String((e && e.stack) || e) + "\n"); process.exit(1); });
export {};
